/**
 * ROUND 78 -- which of the three filtered frames each temple uses, as
 * [main, accent]. Replaces the pairs above, which named four frames the world
 * may no longer place.
 *
 * Every god gets a DIFFERENT pair of the three, so the border ring reads as a
 * border rather than as the same tile with a line drawn round it, and so two
 * temples of similar colour still differ in pattern.
 */
export const TEMPLE_FLOOR_FILTERED = {
  war: [10, 14], dominion: [14, 15], heros: [10, 15], knowledge: [15, 10],
  liberty: [14, 10], healing: [10, 14], purity: [15, 14], death: [14, 15],
};

/** Faults a suite can assert without booting the game. */
export function templeFloorFaults() {
  const out = [];
  for (const g of GODS) {
    if (!TEMPLE_RAMPS[g]) out.push(`${g} has no temple ramp`);
    else if (TEMPLE_RAMPS[g].length !== 6) out.push(`${g}'s ramp has ${TEMPLE_RAMPS[g].length} steps, not 6`);
    const pair = TEMPLE_FLOOR_FILTERED[g];
    if (!pair) { out.push(`${g} has no filtered floor pair`); continue; }
    if (pair[0] === pair[1]) out.push(`${g}'s floor and border are the same frame`);
    for (const f of pair) {
      if (!TEMPLE_FILTER_FRAMES.includes(f)) {
        out.push(`${g} uses frame ${f}, which is not one of the three the user named`);
      }
    }
  }
  // Two gods sharing a ramp would give two temples the same floor, which is
  // the thing the per-god colour exists to prevent.
  const seen = new Map();
  for (const g of GODS) {
    const k = (TEMPLE_RAMPS[g] || []).join(',');
    if (seen.has(k)) out.push(`${g} and ${seen.get(k)} have identical ramps`);
    seen.set(k, g);
  }
  return out;
}
